content:
:root {
  --bg-space: #030712;
  --panel-bg: rgba(15, 23, 42, 0.72);
  --panel-border: rgba(148, 163, 184, 0.18);
  --panel-glow: rgba(56, 189, 248, 0.12);
  --accent-cyan: #38bdf8;
  --accent-blue: #3b82f6;
  --accent-amber: #f59e0b;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --card-bg: rgba(15, 23, 42, 0.85);
  --btn-bg: rgba(30, 41, 59, 0.7);
  --btn-hover: rgba(51, 65, 85, 0.85);
  --btn-active: rgba(56, 189, 248, 0.25);
  --transition-speed: 0.25s;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-space);
  color: var(--text-primary);
  font-family: var(--font-family);
  user-select: none;
}

#root {
  width: 100%;
  height: 100%;
}

/* アプリ全体コンテナ */
.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at center, #070d1e 0%, #030712 100%);
}

/* 3Dキャンバスコンテナ */
.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  outline: none;
}

.canvas-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* UIオーバーレイ共通親 */
.overlay-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 16px;
}

/* 上部ヘッダーパネル */
.header-panel {
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  padding: 12px 16px;
  background: var(--panel-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--panel-border);
  border-radius: 18px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45), 0 0 20px var(--panel-glow);
  transition: all var(--transition-speed) ease;
}

/* 操作ガイド用バナー */
.instructions-banner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
}

.instructions-text {
  font-size: 0.8rem;
  color: var(--text-secondary);
  text-align: center;
  letter-spacing: 0.03em;
}

/* 惑星ナビゲーション */
.planet-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;
  width: 100%;
}

.planet-nav-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--btn-bg);
  border: 1px solid var(--panel-border);
  border-radius: 20px;
  color: var(--text-secondary);
  font-size: 0.825rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  white-space: nowrap;
}

.planet-nav-btn:hover {
  background: var(--btn-hover);
  color: var(--text-primary);
  border-color: rgba(56, 189, 248, 0.4);
  transform: translateY(-1px);
}

.planet-nav-btn.active-nav-btn {
  background: rgba(56, 189, 248, 0.2);
  border-color: var(--accent-cyan);
  color: #e0f2fe;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
  font-weight: 600;
}

/* 下部コントロールパネル */
.control-panel {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 14px;
  margin: 0 auto;
  padding: 10px 20px;
  background: var(--panel-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--panel-border);
  border-radius: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5), 0 0 20px var(--panel-glow);
}

.control-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* 再生・一時停止ボタン */
.play-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, #0284c7, #2563eb);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
}

.play-btn:hover {
  transform: scale(1.06);
  box-shadow: 0 6px 16px rgba(56, 189, 248, 0.5);
  background: linear-gradient(135deg, #0ea5e9, #3b82f6);
}

.play-btn:active {
  transform: scale(0.96);
}

/* 速度コントロール */
.speed-control {
  display: flex;
  align-items: center;
  gap: 8px;
}

.speed-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100px;
  height: 6px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  cursor: pointer;
  transition: background 0.2s;
}

.speed-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
  transition: transform 0.15s ease;
}

.speed-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.speed-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
}

.speed-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
  min-width: 48px;
}

/* 軌道トグル・リセットボタン */
.orbit-toggle, .reset-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: var(--btn-bg);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  color: var(--text-secondary);
  font-size: 0.825rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.orbit-toggle:hover, .reset-btn:hover {
  background: var(--btn-hover);
  color: var(--text-primary);
  border-color: rgba(148, 163, 184, 0.35);
  transform: translateY(-1px);
}

.orbit-toggle.active {
  background: rgba(56, 189, 248, 0.18);
  border-color: var(--accent-cyan);
  color: #e0f2fe;
}

/* 詳細情報モーダル / カード */
.info-card {
  pointer-events: auto;
  position: absolute;
  top: 90px;
  right: 20px;
  width: 330px;
  max-height: calc(100vh - 180px);
  overflow-y: auto;
  background: var(--card-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 18px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.65), 0 0 24px var(--panel-glow);
  animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 20;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(20px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

.info-card::-webkit-scrollbar {
  width: 4px;
}

.info-card::-webkit-scrollbar-track {
  background: transparent;
}

.info-card::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.2);
  border-radius: 2px;
}

.info-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid rgba(148, 163, 184, 0.15);
  padding-bottom: 12px;
}

.info-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.info-subtitle {
  font-size: 0.8rem;
  color: var(--accent-cyan);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
}

.close-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.close-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.info-stat {
  background: rgba(30, 41, 59, 0.5);
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.1);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-label {
  font-size: 0.72rem;
  color: var(--text-muted);
}

.stat-value {
  font-size: 0.85rem;
  font-weight: 600;
  color: #e2e8f0;
  word-break: break-all;
}

.info-desc {
  font-size: 0.825rem;
  line-height: 1.55;
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.4);
  padding: 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.08);
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 0.7rem;
  font-weight: 600;
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent-cyan);
  border: 1px solid rgba(56, 189, 248, 0.3);
}

/* スマホ・タブレット向けレスポンシブ対応 */
@media (max-width: 768px) {
  .overlay-container {
    padding: 10px;
  }

  .header-panel {
    padding: 8px 12px;
    gap: 8px;
  }

  .planet-nav {
    overflow-x: auto;
    flex-wrap: nowrap;
    justify-content: flex-start;
    padding-bottom: 4px;
    -webkit-overflow-scrolling: touch;
  }

  .planet-nav::-webkit-scrollbar {
    height: 3px;
  }

  .planet-nav::-webkit-scrollbar-thumb {
    background: rgba(148, 163, 184, 0.2);
    border-radius: 3px;
  }

  .planet-nav-btn {
    padding: 5px 10px;
    font-size: 0.75rem;
    flex-shrink: 0;
  }

  .control-panel {
    padding: 8px 14px;
    gap: 10px;
    width: 100%;
    max-width: 480px;
  }

  .speed-slider {
    width: 70px;
  }

  .info-card {
    top: auto;
    bottom: 80px;
    right: 10px;
    left: 10px;
    width: auto;
    max-height: 48vh;
  }

  .instructions-banner {
    display: none;
  }
}

export interface PlanetInfo {
  id: string;
  name: string;
  englishName: string;
  radius: number;
  orbitRadius: number;
  orbitSpeed: number;
  rotationSpeed: number;
  color: string;
  emissive?: string;
  hasRing?: boolean;
  ringInnerRadius?: number;
  ringOuterRadius?: number;
  ringColor?: string;
  description: string;
  mass: string;
  orbitalPeriod: string;
  rotationPeriod: string;
  temperature: string;
}

export interface SimulationSettings {
  speed: number;
  isPaused: boolean;
  showOrbits: boolean;
  focusedPlanetId: string | null;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { PlanetInfo, SimulationSettings } from './types';
import { planetsData } from './planetsData';

interface SolarSystemCanvasProps {
  settings: SimulationSettings;
  onSelectPlanet: (id: string | null) => void;
}

interface PlanetMeshEntry {
  info: PlanetInfo;
  group: THREE.Group;
  mesh: THREE.Mesh;
  angle: number;
  orbitLine?: THREE.Line;
}

const SolarSystemCanvas = ({
  settings,
  onSelectPlanet
}: SolarSystemCanvasProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const planetMeshesRef = useRef<Map<string, PlanetMeshEntry>>(new Map());
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const controlsRef = useRef<OrbitControls | null>(null);
  const animFrameIdRef = useRef<number>(0);
  const defaultCameraPos = useRef(new THREE.Vector3(0, 80, 160));

  // 最新の設定値をrefで保持しアニメーションループ内で参照
  const settingsRef = useRef<SimulationSettings>(settings);
  useEffect(() => {
    settingsRef.current = settings;
    // 軌道線の可視・不可視切り替え
    planetMeshesRef.current.forEach((entry) => {
      if (entry.orbitLine) {
        entry.orbitLine.visible = settings.showOrbits;
      }
    });
  }, [settings]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 1. シーン・カメラ・レンダラー初期化
    const width = container.clientWidth || window.innerWidth;
    const height = container.clientHeight || window.innerHeight;

    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.fog = new THREE.FogExp2(0x030712, 0.0018);

    const camera = new THREE.PerspectiveCamera(45, width / height, 0.5, 2000);
    camera.position.copy(defaultCameraPos.current);
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    rendererRef.current = renderer;
    container.appendChild(renderer.domElement);

    // OrbitControls 初期化
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.maxDistance = 500;
    controls.minDistance = 5;
    controlsRef.current = controls;

    // 2. 光源
    const ambientLight = new THREE.AmbientLight(0x334155, 1.2);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xffffff, 2.8, 1200, 0.4);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // 3. 背景の星屑パーティクル
    const starCount = 3500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);
    const starColors = new Float32Array(starCount * 3);

    const baseStarColors = [
      new THREE.Color('#38bdf8'),
      new THREE.Color('#f8fafc'),
      new THREE.Color('#fde047'),
      new THREE.Color('#cbd5e1')
    ];

    for (let i = 0; i < starCount; i++) {
      const radius = 400 + Math.random() * 800;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 2 - 1);

      starPositions[i * 3] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = radius * Math.sin(phi) * Math.sin(theta);
      starPositions[i * 3 + 2] = radius * Math.cos(phi);

      const color = baseStarColors[Math.floor(Math.random() * baseStarColors.length)];
      starColors[i * 3] = color.r;
      starColors[i * 3 + 1] = color.g;
      starColors[i * 3 + 2] = color.b;
    }

    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 1.2,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });

    const starField = new THREE.Points(starGeometry, starMaterial);
    scene.add(starField);

    // 4. 太陽と惑星メッシュの構築
    planetsData.forEach((planet) => {
      const isSun = planet.id === 'sun';
      const planetGroup = new THREE.Group();

      let mesh: THREE.Mesh;
      if (isSun) {
        // 太陽
        const sunGeo = new THREE.SphereGeometry(planet.radius, 48, 48);
        const sunMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(planet.color)
        });
        mesh = new THREE.Mesh(sunGeo, sunMat);

        // 太陽のコロナ・グローエフェクト
        const glowGeo = new THREE.SphereGeometry(planet.radius * 1.22, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(planet.emissive || '#ff7700'),
          transparent: true,
          opacity: 0.28,
          side: THREE.BackSide
        });
        const glowMesh = new THREE.Mesh(glowGeo, glowMat);
        mesh.add(glowMesh);
      } else {
        // 惑星
        const sphereGeo = new THREE.SphereGeometry(planet.radius, 32, 32);
        const sphereMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(planet.color),
          roughness: 0.7,
          metalness: 0.15
        });
        mesh = new THREE.Mesh(sphereGeo, sphereMat);

        // 土星などの環（リング）
        if (planet.hasRing && planet.ringInnerRadius && planet.ringOuterRadius) {
          const ringGeo = new THREE.RingGeometry(
            planet.ringInnerRadius,
            planet.ringOuterRadius,
            64
          );
          const ringMat = new THREE.MeshBasicMaterial({
            color: new THREE.Color(planet.ringColor || '#d4b982'),
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.75
          });
          const ringMesh = new THREE.Mesh(ringGeo, ringMat);
          ringMesh.rotation.x = Math.PI / 2.3;
          mesh.add(ringMesh);
        }

        // 軌道ラインの生成
        const orbitPoints: THREE.Vector3[] = [];
        const segments = 128;
        for (let j = 0; j <= segments; j++) {
          const theta = (j / segments) * Math.PI * 2;
          orbitPoints.push(
            new THREE.Vector3(
              Math.cos(theta) * planet.orbitRadius,
              0,
              Math.sin(theta) * planet.orbitRadius
            )
          );
        }
        const orbitGeo = new THREE.BufferGeometry().setFromPoints(orbitPoints);
        const orbitMat = new THREE.LineBasicMaterial({
          color: 0x38bdf8,
          transparent: true,
          opacity: 0.22
        });
        const orbitLine = new THREE.Line(orbitGeo, orbitMat);
        orbitLine.visible = settingsRef.current.showOrbits;
        scene.add(orbitLine);

        // 各エントリに軌道線を紐付け
        planetMeshesRef.current.set(planet.id, {
          info: planet,
          group: planetGroup,
          mesh,
          angle: Math.random() * Math.PI * 2,
          orbitLine
        });
      }

      if (isSun) {
        planetMeshesRef.current.set(planet.id, {
          info: planet,
          group: planetGroup,
          mesh,
          angle: 0
        });
      }

      mesh.userData = { id: planet.id };
      planetGroup.add(mesh);
      scene.add(planetGroup);
    });

    // 5. レイキャスター（惑星クリックによる選択）
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: MouseEvent) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);

      const interactiveMeshes: THREE.Mesh[] = [];
      planetMeshesRef.current.forEach((entry) => {
        interactiveMeshes.push(entry.mesh);
      });

      const intersects = raycaster.intersectObjects(interactiveMeshes, false);
      if (intersects.length > 0) {
        const clickedPlanetId = intersects[0].object.userData.id as string;
        onSelectPlanet?.(clickedPlanetId);
      }
    };

    const domElem = renderer.domElement;
    domElem.addEventListener('pointerdown', handlePointerDown);

    // 6. リサイズハンドラ
    const handleResize = () => {
      if (!containerRef.current || !rendererRef.current || !cameraRef.current) return;
      const newWidth = containerRef.current.clientWidth;
      const newHeight = containerRef.current.clientHeight;
      cameraRef.current.aspect = newWidth / newHeight;
      cameraRef.current.updateProjectionMatrix();
      rendererRef.current.setSize(newWidth, newHeight);
    };

    window.addEventListener('resize', handleResize);

    // 7. アニメーションループ
    const targetCameraPos = new THREE.Vector3();
    const targetLookAt = new THREE.Vector3();

    const animate = () => {
      animFrameIdRef.current = requestAnimationFrame(animate);

      const currentSettings = settingsRef.current;
      const deltaSpeed = currentSettings.isPaused ? 0 : currentSettings.speed;

      // 惑星の公転・自転
      planetMeshesRef.current.forEach((entry) => {
        const { info, mesh, group } = entry;

        // 自転
        mesh.rotation.y += info.rotationSpeed * (currentSettings.isPaused ? 0.2 : currentSettings.speed);

        // 公転
        if (info.orbitRadius > 0) {
          entry.angle += info.orbitSpeed * 0.15 * deltaSpeed;
          const x = Math.cos(entry.angle) * info.orbitRadius;
          const z = Math.sin(entry.angle) * info.orbitRadius;
          mesh.position.set(x, 0, z);
        }
      });

      // 星屑をゆっくり回転
      starField.rotation.y += 0.0001;

      // カメラの惑星追従
      if (currentSettings.focusedPlanetId) {
        const focusedEntry = planetMeshesRef.current.get(currentSettings.focusedPlanetId);
        if (focusedEntry) {
          const planetWorldPos = new THREE.Vector3();
          focusedEntry.mesh.getWorldPosition(planetWorldPos);

          const distanceOffset = Math.max(focusedEntry.info.radius * 4.2, 12);
          targetCameraPos.set(
            planetWorldPos.x + distanceOffset * 0.7,
            planetWorldPos.y + distanceOffset * 0.45,
            planetWorldPos.z + distanceOffset * 0.7
          );
          targetLookAt.copy(planetWorldPos);

          // スムーズなカメラ移動
          camera.position.lerp(targetCameraPos, 0.05);
          controls.target.lerp(targetLookAt, 0.08);
        }
      } else {
        // デフォルト全体視点
        controls.target.lerp(new THREE.Vector3(0, 0, 0), 0.05);
      }

      controls.update();
      renderer.render(scene, camera);
    };

    animate();

    // クリーンアップ
    return () => {
      cancelAnimationFrame(animFrameIdRef.current);
      window.removeEventListener('resize', handleResize);
      domElem.removeEventListener('pointerdown', handlePointerDown);

      controls.dispose();
      renderer.dispose();

      if (container.contains(domElem)) {
        container.removeChild(domElem);
      }
      planetMeshesRef.current.clear();
    };
  }, [onSelectPlanet]);

  return <div ref={containerRef} className="canvas-container" />;
};

export default SolarSystemCanvas;

import { ChangeEvent } from 'react';
import { Play, Pause, RotateCcw, Orbit, X, Compass, Info } from 'lucide-react';
import { PlanetInfo, SimulationSettings } from './types';
import { planetsData } from './planetsData';

interface UIOverlayProps {
  settings: SimulationSettings;
  onUpdateSettings: (newSettings: Partial<SimulationSettings>) => void;
  onSelectPlanet: (id: string | null) => void;
  onResetCamera: () => void;
}

const UIOverlay = ({
  settings,
  onUpdateSettings,
  onSelectPlanet,
  onResetCamera
}: UIOverlayProps) => {
  const focusedPlanet: PlanetInfo | undefined = planetsData.find(
    (p) => p.id === settings.focusedPlanetId
  );

  const handleSpeedChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    onUpdateSettings?.({ speed: val });
  };

  const togglePause = () => {
    onUpdateSettings?.({ isPaused: !settings.isPaused });
  };

  const toggleOrbits = () => {
    onUpdateSettings?.({ showOrbits: !settings.showOrbits });
  };

  return (
    <div className="overlay-container">
      {/* 画面上部ヘッダーパネル */}
      <header className="header-panel">
        <div className="instructions-banner">
          <Compass size={14} color="#38bdf8" />
          <span className="instructions-text">
            ドラッグで3D回転・ホイールでズーム・惑星クリックまたは天体名選択で追従
          </span>
        </div>

        {/* 惑星ナビゲーションバー */}
        <nav className="planet-nav" aria-label="惑星選択ナビゲーション">
          {planetsData.map((planet) => {
            const isSelected = settings.focusedPlanetId === planet.id;
            const buttonClass = isSelected
              ? 'planet-nav-btn active-nav-btn'
              : 'planet-nav-btn';

            return (
              <button
                key={planet.id}
                type="button"
                className={buttonClass}
                onClick={() => {
                  if (isSelected) {
                    onSelectPlanet?.(null);
                  } else {
                    onSelectPlanet?.(planet.id);
                  }
                }}
              >
                <span
                  style={{
                    display: 'inline-block',
                    width: '8px',
                    height: '8px',
                    borderRadius: '50%',
                    backgroundColor: planet.color,
                    boxShadow: `0 0 6px ${planet.color}`
                  }}
                />
                {planet.name}
              </button>
            );
          })}
        </nav>
      </header>

      {/* 選択された天体の詳細情報カード */}
      {focusedPlanet && (
        <aside className="info-card" aria-label="天体詳細情報">
          <div className="info-header">
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <h2 className="info-title">{focusedPlanet.name}</h2>
                <span className="badge">
                  {focusedPlanet.id === 'sun' ? '恒星' : '惑星'}
                </span>
              </div>
              <p className="info-subtitle">{focusedPlanet.englishName}</p>
            </div>
            <button
              type="button"
              className="close-btn"
              onClick={() => onSelectPlanet?.(null)}
              title="フォーカス解除"
              aria-label="詳細パネルを閉じる"
            >
              <X size={18} />
            </button>
          </div>

          <div className="info-grid">
            <div className="info-stat">
              <span className="stat-label">公転周期</span>
              <span className="stat-value">{focusedPlanet.orbitalPeriod}</span>
            </div>
            <div className="info-stat">
              <span className="stat-label">自転周期</span>
              <span className="stat-value">{focusedPlanet.rotationPeriod}</span>
            </div>
            <div className="info-stat">
              <span className="stat-label">質量</span>
              <span className="stat-value">{focusedPlanet.mass}</span>
            </div>
            <div className="info-stat">
              <span className="stat-label">平均気温 / 温度</span>
              <span className="stat-value">{focusedPlanet.temperature}</span>
            </div>
          </div>

          <p className="info-desc">{focusedPlanet.description}</p>
        </aside>
      )}

      {/* 画面下部コントロールパネル */}
      <footer className="control-panel">
        <div className="control-group">
          <button
            type="button"
            className="play-btn"
            onClick={togglePause}
            title={settings.isPaused ? 'シミュレーション再開' : 'シミュレーション一時停止'}
            aria-label={settings.isPaused ? '再生' : '一時停止'}
          >
            {settings.isPaused ? <Play size={18} /> : <Pause size={18} />}
          </button>
        </div>

        <div className="control-group speed-control">
          <span className="stat-label">速度:</span>
          <input
            type="range"
            min="0.1"
            max="5.0"
            step="0.1"
            value={settings.speed}
            onChange={handleSpeedChange}
            className="speed-slider"
            aria-label="シミュレーション速度"
          />
          <span className="speed-label">x{settings.speed.toFixed(1)}</span>
        </div>

        <div className="control-group">
          <button
            type="button"
            className={settings.showOrbits ? 'orbit-toggle active' : 'orbit-toggle'}
            onClick={toggleOrbits}
            title="軌道線の表示切り替え"
          >
            <Orbit size={16} />
            軌道線
          </button>

          <button
            type="button"
            className="reset-btn"
            onClick={onResetCamera}
            title="全体視点へリセット"
          >
            <RotateCcw size={16} />
            全体視点
          </button>
        </div>
      </footer>
    </div>
  );
};

export default UIOverlay;

import { useState, useCallback } from 'react';
import SolarSystemCanvas from './SolarSystemCanvas';
import UIOverlay from './UIOverlay';
import { SimulationSettings } from './types';
import { defaultSettings } from './planetsData';
import './index.css';

const App = () => {
  const [settings, setSettings] = useState<SimulationSettings>(defaultSettings);

  const handleUpdateSettings = useCallback((newSettings: Partial<SimulationSettings>) => {
    setSettings((prev) => ({
      ...prev,
      ...newSettings
    }));
  }, []);

  const handleSelectPlanet = useCallback((id: string | null) => {
    setSettings((prev) => ({
      ...prev,
      focusedPlanetId: id
    }));
  }, []);

  const handleResetCamera = useCallback(() => {
    setSettings((prev) => ({
      ...prev,
      focusedPlanetId: null
    }));
  }, []);

  return (
    <main className="app-container">
      <SolarSystemCanvas
        settings={settings}
        onSelectPlanet={handleSelectPlanet}
      />
      <UIOverlay
        settings={settings}
        onUpdateSettings={handleUpdateSettings}
        onSelectPlanet={handleSelectPlanet}
        onResetCamera={handleResetCamera}
      />
    </main>
  );
};

export default App;
